// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address depositor, uint256 amt) public {
        vm.assume(depositor != address(0));
        amt = bound(amt, 1, 1 ether);

        vm.deal(depositor, amt);
        uint256 before = address(c).balance;

        vm.prank(depositor);
        (bool sent,) = address(c).call{value: amt}("");
        require(sent);

        uint256 afterDeposit = address(c).balance;
        assertTrue(afterDeposit == before + amt);

        vm.prank(depositor);
        uint256 beforeWithdraw = address(c).balance;
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        uint256 afterWithdraw = address(c).balance;

        assertTrue(!ok || afterWithdraw + amt == beforeWithdraw);
    }
}
